package com.gpformer.glucosetransmitter.simulation

import com.gpformer.glucosetransmitter.data.GlucoseRepository
import com.gpformer.glucosetransmitter.model.GlucoseReading
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlin.random.Random

/**
 * Generates synthetic continuous glucose readings for demonstration and testing.
 *
 * NOTE: All readings generated by this simulator are explicitly flagged with
 * source="simulated" to ensure clear medical distinction from real clinical CGM hardware.
 *
 * Simulates human glucose dynamics using a bounded random walk with momentum and
 * physiological homeostasis drift towards ~115 mg/dL.
 */
class GlucoseSimulator(
    private val repository: GlucoseRepository,
    private val onReadingGenerated: (GlucoseReading) -> Unit
) {
    private val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())
    private var simulationJob: Job? = null

    private val _isSimulating = MutableStateFlow(false)
    val isSimulating: StateFlow<Boolean> = _isSimulating.asStateFlow()

    private val _intervalSeconds = MutableStateFlow(DEFAULT_INTERVAL_SECONDS)
    val intervalSeconds: StateFlow<Int> = _intervalSeconds.asStateFlow()

    // Internal simulation state variables
    private var currentGlucose: Double = 125.0
    private var currentVelocity: Double = 0.5 // rate of change in mg/dL per step

    /**
     * Updates the simulation frequency interval (in seconds).
     */
    fun setIntervalSeconds(seconds: Int) {
        val clamped = seconds.coerceIn(1, 3600)
        _intervalSeconds.value = clamped
    }

    /**
     * Starts continuous automated reading generation.
     */
    @Synchronized
    fun startSimulation() {
        if (_isSimulating.value) return

        // Pick up starting glucose from the latest stored reading if available
        val latestReading = repository.getChronologicalHistory().lastOrNull()
        if (latestReading != null) {
            currentGlucose = latestReading.glucose
        }

        _isSimulating.value = true
        simulationJob = scope.launch {
            while (isActive && _isSimulating.value) {
                delay(_intervalSeconds.value * 1000L)
                if (!isActive || !_isSimulating.value) break

                val nextReading = generateNextReading()
                repository.addReading(nextReading)
                withContext(Dispatchers.Main) {
                    onReadingGenerated(nextReading)
                }
            }
        }
    }

    /**
     * Stops continuous simulation.
     */
    @Synchronized
    fun stopSimulation() {
        _isSimulating.value = false
        simulationJob?.cancel()
        simulationJob = null
    }

    /**
     * Computes the next simulated glucose measurement using smooth physiological dynamics.
     */
    private fun generateNextReading(): GlucoseReading {
        // Homeostatic pull towards baseline (115 mg/dL)
        val homeostaticPull = (115.0 - currentGlucose) * 0.04

        // Random physiological acceleration (meal absorption, insulin response, noise)
        val acceleration = Random.nextDouble(-1.2, 1.2)

        // Update velocity with momentum damping
        currentVelocity = (currentVelocity * 0.7) + homeostaticPull + acceleration
        currentVelocity = currentVelocity.coerceIn(-6.0, 6.0)

        // Update glucose position
        currentGlucose = (currentGlucose + currentVelocity).coerceIn(65.0, 240.0)

        val seq = repository.nextSequence()
        return GlucoseReading.create(
            sequence = seq,
            glucose = currentGlucose,
            source = GlucoseReading.SOURCE_SIMULATED
        )
    }

    fun release() {
        stopSimulation()
        scope.cancel()
    }

    companion object {
        const val DEFAULT_INTERVAL_SECONDS = 5
    }
}
